/* ==UserStyle==
@name           00_2. Ubuntu Sans Mono Nerd Font Web Font
@namespace      github.com/seenukarthi/Stylus
@version        1.0.0
@description    This loads the ubuntu sans mono nerd font web fonts from seenukarthi.com/web-fonts.
@author         Karthikeyan Vaithilingam
==/UserStyle== */
@-moz-document regexp("https?://.*"),
url-prefix("moz-extension://"),
url-prefix("chrome-extension://") {

    /* Ubuntu Sans Mono Nerd Font - Web Font CSS */
    /* Regular */
    @font-face {
        font-family: 'Ubuntu Sans Mono Nerd Font';
